import 'package:stiv/features/diagnostic/models/hypothesis.dart';


// ─────────────────────────────────────────────────────────────────────────────
// HIPÓTESIS DE ENERGÍA — power_issue (UPS, baterías, fuentes)
// ─────────────────────────────────────────────────────────────────────────────

const energyPowerHypotheses = <Hypothesis>[
  Hypothesis(id: 'poe_failure', label: 'Falla de alimentación PoE', description: 'El switch o inyector PoE no entrega suficiente energía al dispositivo. Puede deberse a un puerto PoE defectuoso, presupuesto de potencia del switch agotado, o incompatibilidad entre el estándar PoE del switch (802.3af/at/bt) y los requerimientos del equipo.', recommendedActions: ['Paso 1 — Confirmar si el LED del puerto PoE en el switch está encendido. Un LED apagado indica que el puerto no está entregando energía.', 'Paso 2 — Conectar el equipo a otro puerto PoE en el mismo switch para descartar que sea un problema de puerto específico.', 'Paso 3 — Verificar el presupuesto de potencia total del switch: acceder a la consola del switch y revisar cuántos watts están en uso vs. la capacidad total (ej. 370W en un switch de 24 puertos).', 'Paso 4 — Si el switch no tiene suficiente presupuesto, conectar un inyector PoE pasivo o activo independiente directamente al equipo.', 'Paso 5 — Confirmar el estándar PoE del equipo (revisar etiqueta o manual): si requiere 802.3at (PoE+, 30W) y el switch solo soporta 802.3af (15W), el equipo no encenderá correctamente.', 'Paso 6 — Si ningún puerto PoE entrega energía, reiniciar el switch y verificar la configuración de PoE en la consola de administración.'], escalationThreshold: 0.30),
  Hypothesis(id: 'power_adapter_failure', label: 'Falla de adaptador de alimentación', description: 'El adaptador DC o fuente de poder del equipo está dañado, entrega voltaje incorrecto o el conector tiene mal contacto. Es una de las causas más comunes y solucionables sin soporte de IA.', recommendedActions: ['Paso 1 — Revisar visualmente el cable del adaptador buscando dobleces, cortes o quemaduras cerca del conector.', 'Paso 2 — Con un multímetro en DC, medir el voltaje en la punta del adaptador. El valor debe coincidir ±5% con el voltaje indicado en la etiqueta del adaptador (ej. 12V DC).', 'Paso 3 — Si el voltaje medido es 0V o muy bajo, el adaptador está dañado: reemplazarlo por uno del mismo voltaje, amperaje igual o superior, y polaridad correcta (positivo en el centro).', 'Paso 4 — Inspeccionar el conector DC en el equipo: verificar que los pines estén rectos y limpios. Un pin doblado o sucio impide el contacto.', 'Paso 5 — Al conectar el adaptador de reemplazo, escuchar si el equipo emite un "clic" de relé o si el LED de encendido parpadea brevemente (señal de que recibe energía).'], escalationThreshold: 0.25),
  Hypothesis(id: 'cable_failure', label: 'Falla de cableado (red/alimentación)', description: 'El cable de red UTP o el cable de alimentación tiene un corte interno, mal contacto en la terminación RJ45, o supera la longitud máxima permitida. En instalaciones antiguas, la degradación del revestimiento es frecuente.', recommendedActions: ['Paso 1 — Pasar el cable por un tester de red (cable tester). Un cable Category 5e o superior debe pasar las 8 líneas. Si alguna falla, hay un corte o mal crimpado.', 'Paso 2 — Inspeccionar los conectores RJ45 en ambos extremos bajo buena luz: los 8 alambres deben verse ordenados y llegar hasta la punta del conector antes del crimpado.', 'Paso 3 — Si el cable supera los 90 metros dentro de paredes o conduit (más 10m de patchcords = 100m total), reemplazarlo o instalar un switch intermediario.', 'Paso 4 — Reemplazar el cable sospechoso por un cable de parcheo corto conocido como bueno y verificar si el equipo enciende.', 'Paso 5 — En cables de alimentación, revisar el breaker/regleta asociada y probar el tomacorriente con otro dispositivo para confirmar que hay corriente eléctrica en el punto.'], escalationThreshold: 0.25),
  Hypothesis(id: 'equipment_internal_failure', label: 'Falla interna del equipo (placa/fusible)', description: 'El equipo tiene un daño interno como un fusible fundido, condensador dañado o falla en la placa principal. Puede ocurrir después de sobretensiones eléctricas o fallas de UPS.', recommendedActions: ['Paso 1 — Con el equipo desconectado de la energía, inspeccionar visualmente si hay componentes quemados, abombados o con olor a quemado (especialmente condensadores en la fuente de poder).', 'Paso 2 — Si el equipo tiene botón de reset de fábrica, mantenerlo presionado 10–15 segundos mientras se conecta la energía; algunos modelos requieren este proceso para recovery.', 'Paso 3 — Verificar si el fabricante proporciona una página de recovery de firmware (ej. modo TFTP): consultar la documentación oficial del modelo específico.', 'Paso 4 — Si el equipo tiene fusibles accesibles (revisibles con multímetro en modo continuidad), verificar si alguno está abierto (sin continuidad) y reemplazarlo con el mismo amperaje.', 'Paso 5 — Documentar el número de serie y modelo antes de enviarlo a servicio técnico autorizado. Solicitar diagnóstico escrito.'], escalationThreshold: 0.50),
  Hypothesis(id: 'electrical_overload', label: 'Sobrecarga eléctrica / disyuntor disparado', description: 'El circuito eléctrico al que está conectado el equipo está sobrecargado y el disyuntor (breaker) se disparó, cortando la energía. También puede ser una regleta sobrecargada o con protección térmica activada.', recommendedActions: ['Paso 1 — Verificar en el tablero eléctrico si algún breaker está en posición intermedia (ni ON ni OFF del todo): eso indica que se disparó. Bajarlo completamente y volver a subirlo.', 'Paso 2 — Revisar la regleta o UPS: algunos tienen un botón de "reset" de protección térmica que debe presionarse después de una sobrecarga.', 'Paso 3 — Calcular la carga total del circuito: sumar los vatios de todos los equipos conectados y comparar con la capacidad del breaker (ej. breaker de 20A × 120V = 2400W máximo, usar máximo 80% = 1920W).', 'Paso 4 — Distribuir equipos en diferentes circuitos o fases eléctricas para balancear la carga.', 'Paso 5 — Si el breaker se dispara repetidamente, hay un cortocircuito en el cableado o un equipo defectuoso en el circuito. Desconectar los equipos uno a uno hasta identificar el causante.'], escalationThreshold: 0.30),
  Hypothesis(id: 'ups_battery_failure', label: 'Batería de UPS agotada o dañada', description: 'La batería interna del UPS superó su vida útil (2–3 años típicamente) o sufrió un daño por calor o descarga profunda. El UPS puede encender pero no sostener la carga ante un corte de energía.', recommendedActions: ['Paso 1 — Revisar el panel frontal del UPS: si hay LED o alarma de "Replace Battery" o "BATT", la batería debe cambiarse.', 'Paso 2 — Conectar el UPS a la energía sin carga (desconectar todos los equipos) y dejarlo cargar 8 horas; luego desconectar la energía principal y medir cuánto tiempo sostiene la carga del panel.', 'Paso 3 — Si el tiempo de autonomía es menor al 50% de las especificaciones del fabricante, la batería está degradada y debe reemplazarse.', 'Paso 4 — Al reemplazar la batería, usar exactamente el mismo voltaje (ej. 12V) y capacidad en Ah igual o superior a la original. Verificar la polaridad antes de conectar.', 'Paso 5 — Después del reemplazo, dejar el UPS cargando 12 horas antes de poner equipos críticos en línea.', 'Paso 6 — Actualizar el firmware del UPS si el fabricante tiene versiones recientes: puede mejorar la gestión de batería.'], escalationThreshold: 0.35),
  Hypothesis(id: 'wrong_voltage_region', label: 'Incompatibilidad de voltaje / región eléctrica', description: 'El equipo está configurado para una tensión eléctrica diferente a la de la instalación (ej. equipo de 220V conectado a 110V o viceversa). También ocurre con adaptadores universales en voltaje incorrecto.', recommendedActions: ['Paso 1 — Revisar la etiqueta de especificaciones eléctricas del equipo (usualmente al fondo o en el panel trasero): verificar el rango de voltaje aceptado (ej. 100–240V o solo 120V).', 'Paso 2 — Medir el voltaje del tomacorriente con un multímetro en AC: en Colombia/Latinoamérica debería ser ~110–127V AC, en Europa ~220–240V.', 'Paso 3 — Si el equipo tiene un selector de voltaje físico (switch pequeño cerca de la entrada de poder), verificar que esté en la posición correcta para la región.', 'Paso 4 — Si el equipo no es compatible con el voltaje local, usar un transformador de aislamiento o regulador de voltaje apropiado.'], escalationThreshold: 0.35),
  Hypothesis(id: 'power_strip_trip', label: 'Regleta o PDU terciaria disparada / quemada', description: 'La fuente de poder y el UPS están bien, pero la regleta (multitoma) intermedia donde se conecta el equipo se ha quemado o su mini-breaker térmico ha saltado.', recommendedActions: ['Paso 1 — Identificar si el equipo está conectado directamente a la pared, a un UPS, o mediante una regleta/multitoma de extensión.', 'Paso 2 — Si hay una regleta, revisar si tiene un pequeño botón de RESET o un switch con luz. Si la luz está apagada, encenderla o presionar RESET.', 'Paso 3 — Desconectar el equipo de la regleta y conectarlo temporalmente directo al tomacorriente de pared para aislar la regleta sospechosa.', 'Paso 4 — Reemplazar regletas genéricas por PDUs de grado industrial o con supresor de picos certificado para evitar que micro-cortos la bloqueen.', 'Paso 5 — Medir la continuidad de la regleta con multímetro desenchufada para confirmar si el cable interno está fracturado por tirones.'], escalationThreshold: 0.25),
  Hypothesis(id: 'ups_inverter_fault', label: 'Falla del inversor del UPS (suena pero no da voltaje)', description: 'El UPS recibe energía, la batería retiene carga y el panel enciende, pero el circuito inversor interno está dañado y no entrega 110V/220V a las salidas de respaldo.', recommendedActions: ['Paso 1 — Conectar un probador de voltaje o un cargador de celular simple a los tomas traseros marcados como "Battery Backup".', 'Paso 2 — Desconectar el UPS de la pared simulando un corte. Si el UPS pita indicando que entró en batería pero el probador se apaga inmediatamente: el inversor está muerto.', 'Paso 3 — Mudar los cables temporalmente a las tomas marcadas como "Surge Only" (si el UPS está enchufado a la pared) para mantener los equipos encendidos mientras se tramita la garantía.', 'Paso 4 — Apagar el UPS por completo, dejar presionado el botón de encendido por 10 segundos buscando un hard-reset de la tarjeta lógica.', 'Paso 5 — El equipo debe ser retirado; extraer la batería para reciclaje y enviar la tarjeta lógica del UPS a disposición final/reparación autorizada.'], escalationThreshold: 0.35),
  // ── Nuevas hipótesis de energía ──────────────────────────────────────────────────────────────────────────────────
  Hypothesis(id: 'poe_budget_exhausted', label: 'Presupuesto PoE del switch agotado', description: 'El switch PoE tiene un presupuesto total de potencia (ej. 370W) que se agota cuando se conectan demasiadas cámaras de alto consumo. Al ago-tarse el presupuesto, los últimos puertos configurados dejan de entregar energía.', recommendedActions: ['Paso 1 — Acceder a la consola web/SSH del switch administrable e ir a la sección de PoE Status. Verificar el watts consumidos vs. capacidad total.', 'Paso 2 — Si el presupuesto está agotado, identificar las cámaras o equipos que consumen más watts (generalmente cámaras PTZ o con calefacción) y priorizarlos.', 'Paso 3 — Reducir la potencia PoE máxima por puerto en los equipos no críticos (ej. limitar a 15W los puertos de cámaras que solo necesitan 802.3af).', 'Paso 4 — Como solución a largo plazo, reemplazar el switch por uno de mayor presupuesto PoE o agregar un inyector PoE independiente para los equipos de mayor consumo.', 'Paso 5 — En switches no administrables, la única opción es reducir el número de equipos PoE o usar inyectores individuales para los equipos que excedan el presupuesto.'], escalationThreshold: 0.25),
  Hypothesis(id: 'wrong_dc_voltage', label: 'Voltaje DC incorrecto o ausencia de voltaje en adaptador', description: 'El adaptador DC entrega un voltaje diferente al requerido por el equipo (demasiado alto o demasiado bajo). Un voltaje bajo hace que el equipo no encienda o se reinicie; un voltaje alto puede dañarlo permanentemente.', recommendedActions: ['Paso 1 — Con un multímetro en modo DC, medir el voltaje entre el pin central positivo y el aro negativo del conector del adaptador. El valor debe coincidir exactamente (±5%) con el indicado en la etiqueta del equipo.', 'Paso 2 — Revisar la etiqueta del equipo: verificar el voltaje (ej. 12V DC), amperaje mínimo (ej. 2A), y la polaridad (positivo en el centro, indicado con ○+).', 'Paso 3 — Si el adaptador entrega voltaje incorrecto: reemplazarlo con uno del mismo voltaje y amperaje igual o mayor. NUNCA conectar un adaptador de mayor voltaje.', 'Paso 4 — Si se sospecha que el equipo recibió un voltaje mayor al correcto, inspeccionar visualmente la placa interna en busca de componentes quemados o abombados antes de volver a conectar.', 'Paso 5 — Para instalaciones permanentes, usar fuentes de poder de rack en lugar de adaptadores de pared: son más estables, confiables y fáciles de monitorear.'], escalationThreshold: 0.25),
  Hypothesis(id: 'power_surge_damage', label: 'Daño por sobretransión eléctrica (rayo/pico)', description: 'Un pico de voltaje (por tormenta eléctrica, maniobra del transformador público o corte abrupto) dañó componentes internos del equipo o la fuente de poder. Puede ocurrir incluso con UPS si la descarga supera su capacidad de supresión.', recommendedActions: ['Paso 1 — Si el fallo ocurrió durante o inmediatamente después de una tormenta eléctrica o un corte de luz, la sobretransión es la causa más probable. Documentar el evento.', 'Paso 2 — Inspeccionar visualmente los equipos afectados: cortes en la fuente de poder, olor a ozono o quemado, y varistores (MOV) reventados son indicadores claros.', 'Paso 3 — Verificar si otros equipos del mismo circuito o rack también fallaron simultáneamente: más de un equipo fallado al mismo tiempo confirma la sobretransión.', 'Paso 4 — Reemplazar el equipo afectado. Instalar supresores de transitorios (SPD — Surge Protective Device) certificados ANSI/IEEE para proteger los nuevos equipos.', 'Paso 5 — Verificar que el UPS tenga la función de supresión de picos activa y que no haya "pasado" el transitorio. Revisar el log del UPS si tiene pantalla o software de monitoreo.'], escalationThreshold: 0.30),
  Hypothesis(id: 'poe_standard_mismatch', label: 'Incompatibilidad de estándar PoE (af/at/bt)', description: 'El switch entrega PoE estándar 802.3af (15.4W) pero la cámara requiere 802.3at (30W) o 802.3bt (60W). El equipo puede encender parcialmente, reiniciarse o no funcionar.', recommendedActions: ['Paso 1 — Revisar la etiqueta o manual del equipo para encontrar el estándar PoE requerido: 802.3af = hasta 15.4W, 802.3at = hasta 30W, 802.3bt = hasta 60W.', 'Paso 2 — Verificar la especificación de los puertos PoE del switch: si solo soporta 802.3af y la cámara requiere 802.3at, no se puede alimentar correctamente.', 'Paso 3 — Solución inmediata: usar un inyector PoE activo independiente (ej. PoE Injector de 30W o 60W) entre el switch y la cámara.', 'Paso 4 — Solución definitiva: reemplazar el switch por uno que soporte el estándar PoE requerido por el dispositivo.', 'Paso 5 — Alternativa: verificar si el equipo puede alimentarse con un adaptador DC auxiliar en lugar de PoE y usar el par de reserva del cable UTP para la alimentación (pasivo).'], escalationThreshold: 0.25),
];

const energyAudioHypotheses = <Hypothesis>[
  Hypothesis(id: 'ups_battery_noise', label: 'Batería de UPS agotada (pitido de alarma)', description: 'El UPS emite pitidos continuos o intermitentes indicando batería baja, falla de batería o sobrecarga. El patrón de pitidos varía por fabricante e indica distintos problemas.', recommendedActions: ['Paso 1 — Consultar el manual del UPS para identificar qué significa el patrón de pitidos (ej. 4 pitidos cada 30s = batería baja en APC).', 'Paso 2 — Verificar el panel LCD del UPS (si tiene): mostrará un código de error específico que indica el tipo de falla.', 'Paso 3 — Conectar el UPS sin carga de equipos y verificar si el pitido cesa: si cesa, hay sobrecarga. Si continúa, la batería está fallando.', 'Paso 4 — Revisar la antigüedad de la batería: si tiene más de 2 años en uso continuo, reemplazarla preventivamente.', 'Paso 5 — Algunos UPS permiten silenciar la alarma temporalmente desde el panel frontal mientras se gestiona el reemplazo de batería.'], escalationThreshold: 0.30),
  Hypothesis(id: 'ups_overload', label: 'Sobrecarga del UPS (alarma activa)', description: 'El UPS está conectado a más carga (watts/VA) de la que puede soportar, activando la alarma de sobrecarga. Si no se corrige, el UPS puede apagarse abruptamente cortando la energía a todos los equipos.', recommendedActions: ['Paso 1 — Verificar el LED o indicador de sobrecarga en el panel del UPS (generalmente un LED rojo o ícono de rayo).', 'Paso 2 — Calcular la carga total: sumar el consumo en Watts de todos los equipos conectados. La carga no debe superar el 80% de la capacidad del UPS (ej. UPS de 1000VA/600W → máximo 480W).', 'Paso 3 — Desconectar equipos no críticos del UPS (monitores, impresoras) hasta que la alarma de sobrecarga desaparezca.', 'Paso 4 — Redistribuir equipos usando una regleta convencional para los equipos que no necesitan respaldo (monitores, teclados).', 'Paso 5 — Si la carga legitima supera la capacidad, instalar un UPS adicional de mayor capacidad o reemplazar el actual.'], escalationThreshold: 0.30),
  Hypothesis(id: 'ups_bypass_mode', label: 'UPS bloqueado en Modo Bypass / Relay atorado', description: 'El UPS está encendido y tiene un ruido de sirena constante o clic seco, pero no respalda porque un corto interno provocó que el relé principal quede "pegado" tirando toda la protección al desvío directo de AC.', recommendedActions: ['Paso 1 — Fijarse en el display LED principal del UPS. Si está rotulado como "Bypass On" "Fault" o un diagrama dibujando una línea recta de entrada a salida.', 'Paso 2 — Cortar suministro, el equipo de atrás se apagará también. El Bypass significa que su batería y regulación están inertes temporalmente por falla trágica de sobrecalentamiento/hardware.', 'Paso 3 — Despejar todo el polvo del UPS e intentar dejarlo enfriando apagado 1 hora e intentar reiniciarlo. Muchos circuitos ByPass se liberan.', 'Paso 4 — Si el ruido "clic-clac" rápido suena en el UPS sin estabilizarse, es el relé de transferencia averiado. Debe repararse electrónicamente.', 'Paso 5 — Cambiar de toma a la pared los servidores inmediatamente porque permanecen sin filtrado transitorio.'], escalationThreshold: 0.35),
  Hypothesis(id: 'socket_ground_fault', label: 'Defecto de toma mural a tierra / Ruido fantasma', description: 'La pared donde está enchufado el NVR o gabinete genera arcos ruidosos, chispas audibles dentro de la caja o carece de la 3ra clavija (polo tierra), retransmitiendo inducción estática al chasis de metal o audio.', recommendedActions: ['Paso 1 — Acercar el oído a la roseta/toma eléctrica de la pared. Si vibra tipo chicharra asimétrica ("fritura"), hay falso contacto suelto.', 'Paso 2 — Usar un probador de tomas (Receptacle Tester de 3 LEDs) para ver si la tierra está ausente o si Neutro/Fase están invertidos.', 'Paso 3 — Desconectar de inmediato si huele a ozono (pescado quemado), es fuego latente atrás del plástico del enchufe.', 'Paso 4 — Reparar la roseta abriendo y atornillando bien el neutro y tierra. No cortar el tercer pin (tierra) de los cables de poder jamás.', 'Paso 5 — En racks grandes, instalar una barra cobrizada sólida y amarrar un cable AWG 8 a la estructura del piso.'], escalationThreshold: 0.30),
];
